// Official brand artwork, fetched 2026-09-14. Sources: ../../BRAND-ASSETS.md.
// Raw RGBA is embedded to keep both HTML files synchronous and fully offline.
import { textureCanvas } from '../core.js';
const data = {"slack": "", "github": "", "notion": "", "lark": ""};
const cache = new Map();
export function appIcon(name) {
  if (!cache.has(name)) cache.set(name, textureCanvas(128,128,(ctx)=>{
    const bytes=Uint8ClampedArray.from(atob(data[name]), c=>c.charCodeAt(0));
    ctx.putImageData(new ImageData(bytes,128,128),0,0);
  }));
  return cache.get(name);
}
